// src/application/services/driveObservationParity.spec.ts
//
// The **observation parity check** — the guard against the failure mode
// this repository has already been bitten by once: an observation whose
// normalisation is wrong on the browser side only does not turn the
// schema-level contract red, and the only symptom is "the trained
// policy behaves oddly in the browser".
//
// The fixture (`drive-observation-fixture.json`) is generated by the
// backend (`scripts/gen_drive_observation_fixture.py`): deterministic
// scene states around the unsignalised junction, and the 23-dim
// observation `app.apps.rl.drive_core` computes for every agent —
// committed in **float64** (the same arithmetic this side runs) and
// cross-checked on the Python side against the core's own float32
// output. The assertion below is therefore the repository's measured
// libm noise floor (1e-9, ADR-009) — NOT a slack. If this spec is red,
// the builder's normalisation has drifted from Python's; fix the
// builder, never the tolerance.

import { describe, it, expect } from 'vitest'
import fixture from '@infrastructure/rl/fixtures/drive-observation-fixture.json'
import { buildDriveObservation, DRIVE_OBS_DIM } from './driveObservation'

interface FixtureVehicle {
  id: string
  isAgent: boolean
  x: number
  y: number
  z: number
  heading: number
  speed: number
  routeProgress: number
}

interface FixtureScenario {
  name: string
  conflictPoint: { x: number; z: number }
  vehicles: FixtureVehicle[]
  agents: string[]
}

interface FixtureExpected {
  scenario: string
  agentId: string
  observation: number[]
}

const SCENARIOS = fixture.scenarios as FixtureScenario[]
const EXPECTED = fixture.expected as FixtureExpected[]

describe('the cooperative driving observation parity', () => {
  it('the fixture pins the 23-dim observation over several scenarios', () => {
    expect(fixture.obs_dim).toBe(DRIVE_OBS_DIM)
    expect(SCENARIOS.length).toBeGreaterThanOrEqual(5)
    expect(EXPECTED.length).toBeGreaterThanOrEqual(10)
  })

  it('the builder reproduces Python’s observation for every pinned state', () => {
    const byScenario = new Map(SCENARIOS.map((scenario) => [scenario.name, scenario]))

    for (const entry of EXPECTED) {
      const scenario = byScenario.get(entry.scenario)
      if (!scenario) throw new Error(`fixture scenario missing: ${entry.scenario}`)
      const selfVehicle = scenario.vehicles.find((v) => v.id === entry.agentId)
      if (!selfVehicle) throw new Error(`fixture vehicle missing: ${entry.agentId}`)

      const observation = buildDriveObservation({
        conflictPoint: scenario.conflictPoint,
        self: {
          x: selfVehicle.x,
          z: selfVehicle.z,
          heading: selfVehicle.heading,
          speed: selfVehicle.speed,
          routeProgress: selfVehicle.routeProgress,
        },
        others: scenario.vehicles
          .filter((v) => v.id !== entry.agentId)
          .map((v) => ({ x: v.x, z: v.z, speed: v.speed })),
      })

      let worst = 0
      let worstIndex = -1
      observation.forEach((value, index) => {
        const delta = Math.abs(value - entry.observation[index]!)
        if (delta > worst) {
          worst = delta
          worstIndex = index
        }
      })
      expect(
        worst,
        `${entry.scenario}/${entry.agentId}: element ${worstIndex} differs by ${worst.toExponential(3)}`,
      ).toBeLessThanOrEqual(1e-9)
    }
  })

  it('the committed vectors are the float64 reference, not the float32 core output', () => {
    // The core's own output is float32; if the fixture ever starts
    // carrying float32-rounded values, the 1e-9 parity above would be
    // unachievable. The probe targets the TRIG-derived elements
    // (bearing idx 3, slot offsets base+1/2) — the flags and the
    // normalised speeds are 0/1 and small ratios that are float32-exact
    // BY NATURE, so a whole-vector heuristic would misfire.
    // The bearing (idx 3) is atan2-derived: a NON-ZERO bearing is never
    // float32-exact (the float64 atan2 result lands between float32
    // neighbours with overwhelming probability). Zero-bearing entries
    // (the junction dead ahead) carry no trig noise and are skipped.
    const probed = EXPECTED.filter((entry) => entry.observation[3] !== 0)
    expect(probed.length).toBeGreaterThan(0)
    for (const entry of probed) {
      const value = entry.observation[3]!
      expect(
        Math.fround(value) === value,
        `${entry.scenario}/${entry.agentId} bearing is float32-exact`,
      ).toBe(false)
    }
  })
})
